  #submit-btn { background: gray; }
}

@layer custom {
  .btn { background: blue; }
}

/* Code Review Comment */
body:has(.active-modal) {
  overflow: hidden;
}

.sidebar {
  container-name: sidebar;
  container-type: inline-size;
}

.card-wrapper {
  container-name: card;
  container-type: inline-size;
}

@container sidebar (min-width: 300px) {
  .card-content { color: blue; }
}

/* Star Rating Component */
.star { color: gray; }

/* Previous Sibling Selector Simulation */
.star:has(~ .star:hover) {
  color: gold;
}
.star:hover {
  color: gold;
}

/* main.css */
@layer framework, custom;

@layer custom {
  p { color: red; }
}

@layer framework {
  p { color: blue; }
}
